const body = $input.first().json.body;
const today = new Date().toISOString().split('T')[0];

const systemContent = 'You are a task extraction assistant for an NGO team. '
  + 'Extract task commitments from WhatsApp messages and return ONLY strict JSON — no markdown, no prose outside the JSON object.\n\n'
  + 'Rules:\n'
  + '- owner: person committing (use sender name for first-person, e.g. "yo" / "me encargo")\n'
  + '- task_title: concise title in the same language as the message\n'
  + '- due_date: resolve relative dates using today (' + today + '), return YYYY-MM-DD or null\n'
  + '- priority: low | normal | high | urgent (default normal; urgent = very imminent deadline)\n'
  + '- confidence: 0.0 to 1.0\n\n'
  + 'Return exactly this JSON shape:\n'
  + '{"intent":"task_creation","owner":"...","task_title":"...","description":null,"due_date":null,"status":"pending","priority":"normal","confidence":0.9}';

return [{
  json: {
    model: 'gpt-4o-mini',
    max_tokens: 512,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: systemContent },
      { role: 'user', content: 'Sender: ' + body.ProfileName + '\nMessage: ' + body.Body }
    ]
  }
}];

const raw = $input.first().json.choices[0].message.content;
const extracted = JSON.parse(raw);
return [{ json: extracted }];
